-- Create "users" table
CREATE TABLE "public"."users" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" character varying NOT NULL,
  "email" character varying NOT NULL,
  "password_hash" character varying NULL,
  "updated_at" timestamptz NOT NULL,
  "created_at" timestamptz NOT NULL,
  PRIMARY KEY ("id")
);
-- Create index "users_email_key" to table: "users"
CREATE UNIQUE INDEX "users_email_key" ON "public"."users" ("email");
-- Create "workspaces" table
CREATE TABLE "public"."workspaces" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" character varying NOT NULL,
  "slug" character varying NOT NULL,
  "collect_key" character varying NOT NULL,
  "ingest_key" character varying NOT NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  PRIMARY KEY ("id")
);
-- Create index "workspaces_collect_key_key" to table: "workspaces"
CREATE UNIQUE INDEX "workspaces_collect_key_key" ON "public"."workspaces" ("collect_key");
-- Create index "workspaces_ingest_key_key" to table: "workspaces"
CREATE UNIQUE INDEX "workspaces_ingest_key_key" ON "public"."workspaces" ("ingest_key");
-- Create index "workspaces_slug_key" to table: "workspaces"
CREATE UNIQUE INDEX "workspaces_slug_key" ON "public"."workspaces" ("slug");
-- Create "memberships" table
CREATE TABLE "public"."memberships" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "role" character varying NOT NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "user_id" bigint NOT NULL,
  "workspace_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "memberships_users_memberships" FOREIGN KEY ("user_id") REFERENCES "public"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "memberships_workspaces_memberships" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "membership_user_id_workspace_id" to table: "memberships"
CREATE UNIQUE INDEX "membership_user_id_workspace_id" ON "public"."memberships" ("user_id", "workspace_id");
-- Create "api_tokens" table
CREATE TABLE "public"."api_tokens" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" character varying NOT NULL,
  "prefix" character varying NOT NULL,
  "secret_hash" character varying NOT NULL,
  "scopes" jsonb NOT NULL,
  "expires_at" timestamptz NULL,
  "revoked_at" timestamptz NULL,
  "last_used_at" timestamptz NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "workspace_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "api_tokens_workspaces_api_tokens" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "api_tokens_prefix_key" to table: "api_tokens"
CREATE UNIQUE INDEX "api_tokens_prefix_key" ON "public"."api_tokens" ("prefix");
-- Create "automations" table
CREATE TABLE "public"."automations" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" character varying NOT NULL,
  "status" character varying NOT NULL DEFAULT 'draft',
  "trigger_event" character varying NOT NULL,
  "definition" character varying NOT NULL DEFAULT '[]',
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "workspace_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "automations_workspaces_automations" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "automation_workspace_id" to table: "automations"
CREATE INDEX "automation_workspace_id" ON "public"."automations" ("workspace_id");
-- Create index "automation_workspace_id_status_trigger_event" to table: "automations"
CREATE INDEX "automation_workspace_id_status_trigger_event" ON "public"."automations" ("workspace_id", "status", "trigger_event");
-- Create "automation_runs" table
CREATE TABLE "public"."automation_runs" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "contact_id" bigint NOT NULL,
  "status" character varying NOT NULL DEFAULT 'active',
  "current_step" bigint NOT NULL DEFAULT 0,
  "resume_at" timestamptz NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "automation_id" bigint NOT NULL,
  "workspace_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "automation_runs_automations_runs" FOREIGN KEY ("automation_id") REFERENCES "public"."automations" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "automation_runs_workspaces_automation_runs" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "automation_runs_automation_id_contact_id" to table: "automation_runs"
CREATE UNIQUE INDEX "automation_runs_automation_id_contact_id" ON "public"."automation_runs" ("automation_id", "contact_id");
-- Create "broadcasts" table
CREATE TABLE "public"."broadcasts" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" character varying NOT NULL,
  "subject" character varying NOT NULL DEFAULT '',
  "from_name" character varying NULL,
  "from_email" character varying NULL,
  "body" character varying NOT NULL DEFAULT '',
  "body_text" character varying NOT NULL DEFAULT '',
  "segment_id" bigint NULL,
  "integration_id" bigint NULL,
  "status" character varying NOT NULL DEFAULT 'draft',
  "scheduled_at" timestamptz NULL,
  "sent_at" timestamptz NULL,
  "recipients_total" bigint NOT NULL DEFAULT 0,
  "sent_count" bigint NOT NULL DEFAULT 0,
  "opened_count" bigint NOT NULL DEFAULT 0,
  "clicked_count" bigint NOT NULL DEFAULT 0,
  "unsubscribed_count" bigint NOT NULL DEFAULT 0,
  "failed_count" bigint NOT NULL DEFAULT 0,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "workspace_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "broadcasts_workspaces_broadcasts" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "broadcast_workspace_id" to table: "broadcasts"
CREATE INDEX "broadcast_workspace_id" ON "public"."broadcasts" ("workspace_id");
-- Create "broadcast_recipients" table
CREATE TABLE "public"."broadcast_recipients" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "contact_id" bigint NOT NULL,
  "status" character varying NOT NULL DEFAULT 'pending',
  "error" character varying NULL,
  "sent_at" timestamptz NULL,
  "opened_at" timestamptz NULL,
  "clicked_at" timestamptz NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "broadcast_id" bigint NOT NULL,
  "workspace_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "broadcast_recipients_broadcasts_recipients" FOREIGN KEY ("broadcast_id") REFERENCES "public"."broadcasts" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "broadcast_recipients_workspaces_broadcast_recipients" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "broadcast_recipients_broadcast_id_contact_id" to table: "broadcast_recipients"
CREATE UNIQUE INDEX "broadcast_recipients_broadcast_id_contact_id" ON "public"."broadcast_recipients" ("broadcast_id", "contact_id");
-- Create index "broadcastrecipient_broadcast_id" to table: "broadcast_recipients"
CREATE INDEX "broadcastrecipient_broadcast_id" ON "public"."broadcast_recipients" ("broadcast_id");
-- Create index "broadcastrecipient_workspace_id_sent_at" to table: "broadcast_recipients"
CREATE INDEX "broadcastrecipient_workspace_id_sent_at" ON "public"."broadcast_recipients" ("workspace_id", "sent_at");
-- Create "contacts" table
CREATE TABLE "public"."contacts" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "subject_id" character varying NULL,
  "email" character varying NULL,
  "phone" character varying NULL,
  "first_name" character varying NULL,
  "last_name" character varying NULL,
  "status" character varying NOT NULL DEFAULT 'active',
  "time_zone" character varying NULL,
  "custom_fields" jsonb NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "workspace_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "contacts_workspaces_contacts" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "contacts_email_workspace_id" to table: "contacts"
CREATE UNIQUE INDEX "contacts_email_workspace_id" ON "public"."contacts" ("email", "workspace_id");
-- Create index "contacts_phone_workspace_id" to table: "contacts"
CREATE UNIQUE INDEX "contacts_phone_workspace_id" ON "public"."contacts" ("phone", "workspace_id");
-- Create index "contacts_subject_id_workspace_id" to table: "contacts"
CREATE UNIQUE INDEX "contacts_subject_id_workspace_id" ON "public"."contacts" ("subject_id", "workspace_id");
-- Create "custom_fields" table
CREATE TABLE "public"."custom_fields" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "key" character varying NOT NULL,
  "name" character varying NOT NULL,
  "type" character varying NOT NULL DEFAULT 'string',
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "workspace_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "custom_fields_workspaces_custom_fields" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "custom_fields_key_workspace_id" to table: "custom_fields"
CREATE UNIQUE INDEX "custom_fields_key_workspace_id" ON "public"."custom_fields" ("key", "workspace_id");
-- Create "email_templates" table
CREATE TABLE "public"."email_templates" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" character varying NOT NULL,
  "subject" character varying NOT NULL DEFAULT '',
  "body" character varying NOT NULL DEFAULT '',
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "workspace_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "email_templates_workspaces_email_templates" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "emailtemplate_workspace_id" to table: "email_templates"
CREATE INDEX "emailtemplate_workspace_id" ON "public"."email_templates" ("workspace_id");
-- Create "events" table
CREATE TABLE "public"."events" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "source_id" character varying NULL,
  "contact_id" bigint NULL,
  "visitor_id" character varying NULL,
  "subject_id" character varying NULL,
  "email" character varying NULL,
  "phone" character varying NULL,
  "action" character varying NOT NULL,
  "properties" jsonb NULL,
  "occurred_at" timestamptz NULL,
  "created_at" timestamptz NOT NULL,
  "workspace_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "events_workspaces_events" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "event_workspace_id_contact_id_action" to table: "events"
CREATE INDEX "event_workspace_id_contact_id_action" ON "public"."events" ("workspace_id", "contact_id", "action");
-- Create index "event_workspace_id_visitor_id" to table: "events"
CREATE INDEX "event_workspace_id_visitor_id" ON "public"."events" ("workspace_id", "visitor_id");
-- Create index "events_source_id_key" to table: "events"
CREATE UNIQUE INDEX "events_source_id_key" ON "public"."events" ("source_id");
-- Create "integrations" table
CREATE TABLE "public"."integrations" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" character varying NOT NULL,
  "channel" character varying NOT NULL DEFAULT 'email',
  "provider" character varying NOT NULL,
  "config_encrypted" character varying NOT NULL,
  "enabled" boolean NOT NULL DEFAULT true,
  "is_default" boolean NOT NULL DEFAULT false,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "workspace_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "integrations_workspaces_integrations" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "integration_workspace_id_channel" to table: "integrations"
CREATE UNIQUE INDEX "integration_workspace_id_channel" ON "public"."integrations" ("workspace_id", "channel") WHERE is_default;
-- Create "segments" table
CREATE TABLE "public"."segments" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" character varying NOT NULL,
  "type" character varying NOT NULL DEFAULT 'rule',
  "definition" character varying NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "workspace_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "segments_workspaces_segments" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create "suppressions" table
CREATE TABLE "public"."suppressions" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "email" character varying NOT NULL,
  "reason" character varying NOT NULL DEFAULT 'manual',
  "contact_id" bigint NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "workspace_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "suppressions_workspaces_suppressions" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "suppressions_workspace_id_email" to table: "suppressions"
CREATE UNIQUE INDEX "suppressions_workspace_id_email" ON "public"."suppressions" ("workspace_id", "email");
-- Create "visitors" table
CREATE TABLE "public"."visitors" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "visitor_id" character varying NOT NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "last_seen_at" timestamptz NOT NULL,
  "contact_id" bigint NULL,
  "workspace_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "visitors_contacts_visitors" FOREIGN KEY ("contact_id") REFERENCES "public"."contacts" ("id") ON UPDATE NO ACTION ON DELETE SET NULL,
  CONSTRAINT "visitors_workspaces_visitors" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "visitors_visitor_id_workspace_id" to table: "visitors"
CREATE UNIQUE INDEX "visitors_visitor_id_workspace_id" ON "public"."visitors" ("visitor_id", "workspace_id");
-- Create "webhook_endpoints" table
CREATE TABLE "public"."webhook_endpoints" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "url" character varying NOT NULL,
  "secret_encrypted" character varying NOT NULL,
  "event_types" jsonb NULL,
  "enabled" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "workspace_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "webhook_endpoints_workspaces_webhook_endpoints" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "webhookendpoint_workspace_id" to table: "webhook_endpoints"
CREATE INDEX "webhookendpoint_workspace_id" ON "public"."webhook_endpoints" ("workspace_id");
-- Create index "webhookendpoint_workspace_id_enabled" to table: "webhook_endpoints"
CREATE INDEX "webhookendpoint_workspace_id_enabled" ON "public"."webhook_endpoints" ("workspace_id", "enabled");
